-- UUID generation uses built-in PostgreSQL gen_random_uuid().
create table public.seasons(id uuid primary key default gen_random_uuid(),name text not null,slug text unique not null,registration_open_at timestamptz not null,registration_close_at timestamptz not null,submission_global_close_at timestamptz not null,judging_at timestamptz not null,announcement_at timestamptz not null,shipping_at timestamptz not null,quota integer check(quota>0),is_active boolean default false,created_at timestamptz default now(),updated_at timestamptz default now());
create unique index one_active_season on seasons(is_active) where is_active;
create table public.admin_profiles(user_id uuid primary key references auth.users(id),display_name text not null,role text not null check(role in ('super_admin','admin','judge')),created_at timestamptz default now());
create table public.participants(id uuid primary key default gen_random_uuid(),full_name text not null,public_name text not null,age integer check(age between 1 and 18),school_name text not null,parent_name text not null,whatsapp text not null,instagram_username text not null,address_line text not null,province_code text not null,province_name text not null,regency_code text not null,regency_name text not null,district_code text not null,district_name text not null,village_code text not null,village_name text not null,postal_code text not null check(postal_code ~ '^[0-9]{5}$'),created_at timestamptz default now(),updated_at timestamptz default now());
create table public.registrations(id uuid primary key default gen_random_uuid(),season_id uuid not null references seasons(id),participant_id uuid not null references participants(id),registration_code text unique not null,competition_type text not null check(competition_type in ('photogenic','coloring')),category text not null check(category in ('preschool','paud','tk','sd_1_2','sd_3_4','sd_5_6')),dream_job text not null,class_label text,registration_source text not null default 'website' check(registration_source in ('website','instagram_dm','admin_manual')),registration_status text not null default 'registered' check(registration_status in ('registered','verified','cancelled','disqualified')),payment_status text not null default 'pending' check(payment_status in ('pending','paid','rejected','refunded')),consent_parent_guardian boolean not null check(consent_parent_guardian),consent_publication boolean not null check(consent_publication),consent_terms boolean not null check(consent_terms),consent_fee boolean not null check(consent_fee),consented_at timestamptz not null default now(),created_at timestamptz default now(),updated_at timestamptz default now(),check(not(competition_type='coloring' and category='preschool')));
create table public.participant_media(id uuid primary key default gen_random_uuid(),registration_id uuid not null references registrations(id),storage_path text not null,mime_type text not null,size_bytes integer not null check(size_bytes<=2097152),status text default 'private',created_at timestamptz default now());
create table public.submissions(id uuid primary key default gen_random_uuid(),registration_id uuid not null references registrations(id),submission_type text not null,private_file_path text not null,public_file_path text,slug text unique default substr(replace(gen_random_uuid()::text,'-',''),1,24),status text not null default 'pending_review' check(status in ('pending_review','approved','revision_required','rejected')),publication_status text not null default 'hidden' check(publication_status in ('hidden','approved')),submitted_at timestamptz default now(),reviewed_at timestamptz,reviewed_by uuid references auth.users(id),review_note text,created_at timestamptz default now(),updated_at timestamptz default now(),check((publication_status='approved' and status='approved' and public_file_path is not null) or (publication_status='hidden' and public_file_path is null)));
create unique index one_current_submission on submissions(registration_id) where status in ('pending_review','approved');
create table public.worksheets(id uuid primary key default gen_random_uuid(),registration_id uuid not null references registrations(id),private_file_path text not null,version integer not null,created_by uuid references auth.users(id),created_at timestamptz default now(),unique(registration_id,version));
create table public.judging_scores(id uuid primary key default gen_random_uuid(),submission_id uuid not null references submissions(id),judge_id uuid not null references auth.users(id),criteria jsonb not null,total_score numeric not null check(total_score between 0 and 100),notes text,created_at timestamptz default now(),updated_at timestamptz default now(),unique(submission_id,judge_id));
create table public.results(id uuid primary key default gen_random_uuid(),registration_id uuid unique not null references registrations(id),final_score numeric not null,award_code text not null check(award_code in ('Juara Utama 1','Juara Utama 2','Juara Utama 3','Juara Harapan 1','Juara Harapan 2','Juara Harapan 3','Juara Favorit 1','Juara Favorit 2','Juara Favorit 3','Juara Umum','Best Social Media')),is_published boolean default false,published_at timestamptz,created_at timestamptz default now(),updated_at timestamptz default now());
create table public.payments(id uuid primary key default gen_random_uuid(),registration_id uuid not null references registrations(id),payment_type text not null check(payment_type in ('registration','award_claim')),amount integer not null,status text not null default 'pending' check(status in ('pending','paid','rejected','refunded')),verified_by uuid references auth.users(id),verified_at timestamptz,admin_note text,created_at timestamptz default now(),updated_at timestamptz default now(),unique(registration_id,payment_type));
create table public.claim_invoices(id uuid primary key default gen_random_uuid(),registration_id uuid unique not null references registrations(id),invoice_number text unique not null,amount integer not null default 120000 check(amount=120000),status text not null default 'issued' check(status in ('draft','issued','paid','cancelled')),created_at timestamptz default now(),paid_at timestamptz);
create table public.shipments(id uuid primary key default gen_random_uuid(),registration_id uuid unique not null references registrations(id),courier text not null,tracking_number text,shipping_status text not null default 'waiting' check(shipping_status in ('waiting','prepared','shipped','delivered')),shipped_at timestamptz,delivered_at timestamptz,created_at timestamptz default now(),updated_at timestamptz default now());
create table public.admin_audit_logs(id uuid primary key default gen_random_uuid(),admin_user_id uuid references auth.users(id),action text not null,entity_type text not null,entity_id uuid,before_data jsonb,after_data jsonb,created_at timestamptz default now());
create table public.event_settings(id uuid primary key default gen_random_uuid(),season_id uuid not null references seasons(id),key text not null,value jsonb not null,created_at timestamptz default now(),updated_at timestamptz default now(),unique(season_id,key));
create table public.rate_limits(key text primary key,hits integer not null,window_at timestamptz not null);
create index registrations_filters on registrations(season_id,competition_type,category,payment_status,created_at);
create index participants_province on participants(province_code);
create index submissions_review on submissions(status,publication_status);
create index shipments_status on shipments(shipping_status);
create function public.admin_role() returns text language sql stable security definer set search_path=public as $$select role from admin_profiles where user_id=auth.uid()$$;
revoke all on function public.admin_role() from public; grant execute on function public.admin_role() to authenticated;
do $$declare t text;begin foreach t in array array['seasons','participants','registrations','participant_media','submissions','worksheets','judging_scores','results','payments','claim_invoices','shipments','admin_profiles','admin_audit_logs','event_settings','rate_limits'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from anon,authenticated',t);if t<>'rate_limits' then execute format('grant select on public.%I to authenticated',t);execute format('create policy admin_read on public.%I for select to authenticated using (public.admin_role() in (''admin'',''super_admin''))',t);end if;end loop;end$$;
create policy own_profile on admin_profiles for select to authenticated using(user_id=auth.uid());
create policy judge_submissions on submissions for select to authenticated using(public.admin_role()='judge' and status='approved');
create policy judge_scores on judging_scores for select to authenticated using(public.admin_role()='judge' and judge_id=auth.uid());
create policy public_seasons on seasons for select to anon using(true);grant select on seasons to anon;
create view public.public_gallery with (security_barrier=true) as select s.slug,s.public_file_path,s.created_at,p.public_name,p.regency_name,p.province_name,r.competition_type,r.category,r.season_id from submissions s join registrations r on r.id=s.registration_id join participants p on p.id=r.participant_id where s.status='approved' and s.publication_status='approved' and r.payment_status='paid' and r.registration_status='verified' and r.consent_publication;
create view public.public_results with (security_barrier=true) as select x.award_code,x.final_score,p.public_name,p.regency_name,p.province_name,r.competition_type,r.category,r.season_id from results x join registrations r on r.id=x.registration_id join participants p on p.id=r.participant_id join seasons e on e.id=r.season_id where x.is_published and now()>=e.announcement_at and r.registration_status='verified' and r.consent_publication;
grant select on public_gallery,public_results to anon,authenticated;
create function public.consume_rate_limit(p_key text,p_limit integer) returns boolean language plpgsql security definer set search_path=public as $$declare n integer;begin insert into rate_limits values(p_key,1,now()) on conflict(key) do update set hits=case when rate_limits.window_at<now()-interval '10 minutes' then 1 else rate_limits.hits+1 end,window_at=case when rate_limits.window_at<now()-interval '10 minutes' then now() else rate_limits.window_at end returning hits into n;delete from rate_limits where window_at<now()-interval '1 day';return n<=p_limit;end$$;
revoke all on function consume_rate_limit(text,integer) from public,anon,authenticated;grant execute on function consume_rate_limit(text,integer) to service_role;
create function public.audit_mutation() returns trigger language plpgsql security definer set search_path=public as $$declare actor uuid;begin actor:=coalesce(auth.uid(),nullif(current_setting('app.actor',true),'')::uuid);if actor is not null then insert into admin_audit_logs(admin_user_id,action,entity_type,entity_id,before_data,after_data) values(actor,TG_OP,TG_TABLE_NAME,coalesce((to_jsonb(new)->>'id')::uuid,(to_jsonb(old)->>'id')::uuid),case when TG_OP<>'INSERT' then to_jsonb(old) end,case when TG_OP<>'DELETE' then to_jsonb(new) end);end if;return coalesce(new,old);end$$;
do $$declare t text;begin foreach t in array array['participants','registrations','submissions','worksheets','judging_scores','results','payments','claim_invoices','shipments','seasons','event_settings','admin_profiles'] loop execute format('create trigger audit after insert or update or delete on %I for each row execute function audit_mutation()',t);end loop;end$$;
